+  return `'${packageName}': ${bumpType}`;
+}
+
+/**
+ * Format an npm package@version specifier.
+ * @param {string} packageName
+ * @param {string} version
+ * @returns {string}
+ */
+export function formatNpmPackageVersion(packageName, version) {
+  return `${packageName}@${version}`;
+}

