+
+  if (!isSupportedNodeVersion(nodeVersion)) {
+    failUnsupportedNodeVersion(nodeVersion);
+  }
+
+  const currentResult = await $`npm --version`.run({ capture: true });
+  const currentVersion = currentResult.stdout.trim();
