+    const installedPackageJson = readJsonFile(
+      getInstalledPackageJsonPath(workspace, packageName)
+    );
+
+    checkConfiguredLibraryEntryPoint({
+      installedPackageJson,
+      packageName,
+      runCommandFn,
+      skipLibrary,
+      stdout,
+      workspace,
+    });
+
+    checkConfiguredCliEntryPoints({
+      cliArgs,
+      installedPackageJson,
+      packageName,
+      runCommandFn,
+      skipCli,
+      stdout,
+      workspace,
+    });
