+    await smokeTestPackage({
+      ...config,
+      packageName: packageInfo.name,
+      stdout: (message) => stdout(`[smoke-test] ${message}`),
+    });
+    return 0;
+  } catch (error) {
+    stderr(`[smoke-test] FAILED: ${error.message}`);
+    return 1;
+  }
+}
+
+if (isCliEntryPoint()) {
+  process.exitCode = await main();
+}

