+
+fn installed_binary_path(install_root: &Path, bin_name: &str) -> PathBuf {
+    install_root
+        .join("bin")
+        .join(format!("{bin_name}{}", env::consts::EXE_SUFFIX))
+}
+
+fn check_cli_entrypoints(
+    entrypoints: &EntryPoints,
+    install_root: Option<&Path>,
