+    for bin_name in &entrypoints.bin_names {
+        let bin_path = installed_binary_path(install_root, bin_name);
+        if !bin_path.exists() {
+            return Err(format!(
+                "Expected installed binary {} was not found",
+                bin_path.display()
+            ));
+        }
